namespace PokeStream.Connect;
// Species gender ratios (format facts, source and revision in SOURCES.md).
internal static class ClassicGender {
    private static readonly byte[] Gen2=Convert.FromHexString("");
    private static readonly byte[] Gen3=Convert.FromHexString("");
    public static int Read(int generation,int species,uint value) {
        var ratios=generation==2?Gen2:Gen3;int ratio=ratios[species];
        return ratio switch {255=>2,254=>1,0=>0,_=>generation==2?(value>(ratio>>4)?0:1):((value&255)<ratio?1:0)};
    }
}
